"""Task-oriented instructions, kept as editable text rather than table cells."""
OPS = {
'18.1': ('构建完成后，普通 EFB 可通过工程根目录的启动脚本打开。首次构建请先按第3章安装依赖并执行 npm run build。', ['双击“启动EFB.cmd”，或在终端执行 npm start。', '打开 http://127.0.0.1:9697/，等待加载提示结束并进入主页面。', '工作结束前导出需要保留的航班 JSON；若已生成有效结果，再导出报告。', '关闭标签页结束查看。需要停止后台服务时，执行 Stop-EFB.ps1；前台 npm 服务用 Ctrl+C 停止。'], '再次打开相同地址会连接仍在运行的服务。关闭浏览器不会自动结束后台进程。'),
'18.2': ('主页用于快速查看当前航班和各模块入口。没有确认本地航班时，部分摘要为空。', ['先查看顶部机场、时间和连接图标，识别当前页面环境。', '通过左侧图标进入签派、地面、性能、航图或检查单。', '已有航班时，核对主页机场和航班摘要是否与工作台一致。'], '主页中的进度与位置依赖宿主变量；本地演示显示的是样例状态。'),
'18.3': ('一级图标切换业务域，页面上方的标签切换该业务域内的功能。', ['点击左侧目标图标，再选择页面顶部所需标签。', '在本地工作台中，也可使用“原生燃油页面”“原生载重页面”和“查看本地签派资料”直接跳转。', '从设置页面返回时使用 EFB 内部导航。'], '内部路由由应用管理，浏览器地址栏不逐项反映当前标签。浏览器刷新会重新装载整个 EFB。'),
'18.4': ('顶部齿轮打开快速控制面板，面板提供显示、休眠和连接等常用操作。', ['点击顶部齿轮，展开快速控制。', '需要暂时隐藏页面时，选择休眠。', '回到休眠画面后点击“唤醒 EFB”，恢复平板界面。', '若选择了关机，使用“开启 EFB”重新进入。'], '休眠和关机控制平板页面状态，不停止本机 Node 服务。'),
'18.5': ('语言和主题属于平板阅读偏好，可在设置中调整。', ['进入设置并打开平板显示相关页面。', '选择所需语言和主题，观察菜单及背景更新。', '查看时间显示方式；航班工作台日期仍按 UTC 字段录入。'], '重量、长度和气压单位在相应业务控件中选择。不要用显示语言推断计算单位。'),
'18.6': ('启动异常先按服务、入口和页面三个层次定位。', ['确认启动命令没有报错，并用浏览器打开 /__health 检查服务响应。', '若缺少构建产物，在工程根目录运行 npm run build，再重新启动。', '加载后仍有错误提示时，保留提示文字，并查看 logs 中的服务日志和浏览器控制台。', '窗口过窄时扩大窗口或使用全屏；长页面继续在内容区向下滚动。'], '航图或 SimBridge 连接失败只影响对应服务入口，不表示整个本地 EFB 未启动。'),
'19.1': ('本地航班工作台位于签派业务域，建立新航班会替换当前草稿。', ['打开“本地航班”页面，先导出需要保留的当前输入。', '点击“新建航班”，读取新建后的标识、日期和默认数据。', '按本次演示计划修改输入，检查顶部质量卡片随输入变化。'], '新建后的默认值仍是样例，需要核对后点击“保存并确认重量”。'),
'19.2': ('航班号、UTC 日期、起降机场和航路在工作台的“航班信息”区域填写。', ['输入航班号和日期。', '填写起飞、目的和备降机场代码；起飞及目的机场使用四位 ICAO 代码。', '在航路文字框填写需要展示的航路说明。', '点击“保存并确认重量”，根据提示修正未通过校验的字段。'], '当前航路字段为文本，不会自动解析导航数据库或生成真实航路距离。'),
'19.3': ('航班 JSON 保存当前输入，可供重新导入和异机继续编辑。', ['点击“导出航班 JSON”。', '在浏览器下载位置找到 local-flight.json，按日期和航班自行整理文件名。', '需要保留计算快照时，另行导出结果 JSON 或 HTML 报告。'], '航班文件不是计算结果文件；导入后仍需确认和计算。'),
'19.4': ('导入动作先解析并校验整个文件，通过后才替换当前航班。', ['点击“导入航班 JSON”并选择本系统导出的航班文件。', '导入成功后核对航班号、机场、旅客人数和燃油。', '若提示格式、机型或字段错误，修正文件后重新选择。', '点击“保存并确认重量”，再进入后续页面。'], '导入文本超过 100 000 个字符或校验失败时，页面保留原航班。结果 JSON 与航班 JSON 的结构不同，不应混用。'),
'19.5': ('确认动作把当前 Flight 投影到原生仪表盘、签派和地面目标。', ['在工作台核对人数、每名旅客质量、行李、货物和燃油。', '点击“保存并确认重量”，检查确认提示。', '打开仪表盘，核对起降机场和航班摘要。', '进入燃油或载重页面，检查页面顶部显示的本地计划身份。'], '修改任一输入后，先前确认失效；需要重新确认才可计算。'),
'19.6': ('本地签派资料由当前已确认航班生成，可在 OFP 阅读器内查看。', ['在工作台点击“查看本地签派资料”，或进入签派的 OFP 标签。', '核对航班标识、起降机场、ZFW、燃油和 TOW。', '通过阅读器控件调整缩放，向下滚动查看完整内容。'], '页面标有本地手工计划来源，其中预计时刻等兼容字段不代表外部签派计算。'),
'20.1': ('演示样例使用 250 名旅客，每名旅客 80 kg、行李 24 kg，额外货物 2 000 kg。', ['在工作台填写旅客人数、每名旅客质量及行李质量。', '填写额外货物，观察载荷、ZFW 和 TOW 卡片。', '按样例核对载荷为 28 000 kg、ZFW 为 155 000 kg。', '将人数临时改为 260，观察 TOW 增加 1 040 kg；恢复 250 后再确认。'], '运行空重由当前资料包固定为 127 000 kg，页面不允许直接修改。'),
'20.2': ('停机坪燃油参与停机坪质量，滑行耗油用于从该质量计算 TOW。', ['输入停机坪燃油 30 000 kg 和滑行耗油 500 kg。', '检查 TOW 为 184 500 kg。', '需要使用 lb 时切换“重量显示单位”，核对各字段显示值。', '完成修改后重新确认。'], '单位切换只改变显示与录入换算，内部仍保存 kg。滑行耗油不能大于停机坪燃油。'),
'20.3': ('原生燃油页显示油箱当前量、目标量及相关控制。', ['先确认本地航班，再点击“原生燃油页面”。', '读取总目标及各油箱的当前、目标显示。', '将总目标从 30 000 kg 改为 31 000 kg，返回本地航班页面。', '点击“读取地面燃油目标”，核对工作台燃油已更新，再确认。'], '改变目标后旧参考结果失效。目标变化本身不表示真实加油已经完成。'),
'20.4': ('原生载重页提供座位、货舱和计划质量视图。', ['确认航班后打开“原生载重页面”。', '核对计划人数和质量，并查看座位分布。', '向内容区底部滚动，找到装载及进度控件。', '若人工改变地面目标，返回工作台检查提示并重新确认。'], '浏览器宿主呈现的是本地计划和样例变量，不能据此判断真实乘机或货物装载完成。'),
'20.5': ('地面目标变化先标记旧结果过期，不自动重写整个 Flight。', ['在燃油页改变目标后，回到起飞核算页查看“结果已过期”提示。', '返回工作台，点击“读取地面燃油目标”。', '核对新的停机坪燃油及 TOW，点击“保存并确认重量”。', '重新运行计算，再保存新记录或报告。'], '在样例中，燃油增加 1 000 kg 后 TOW 为 185 500 kg，CONF 1+F 的 V2 参考为 151.2 kt。'),
'20.6': ('地服和推出页保留原生按钮、状态和专业操作区域。', ['进入地面服务，查看舱门、车辆和设备入口。', '观察控件是否可用以及页面显示的当前状态。', '切换到推出页，查看方向和相关控制后返回。'], '本地浏览器没有连接真实飞机或推出服务。此处用于展示页面和控制入口，不以按钮响应证明飞机已发生位移。'),
'21.1': ('跑道和天气用于本次参考核算，样例资料为手工演示输入。', ['进入“离线起飞核算”，填写跑道编号、航向及 TORA、TODA、ASDA。', '填写标高、坡度和入口距离扣减，确认显示单位。', '填写风向、风速、气温和 QNH，必要时切换气压显示单位。', '检查跑道条件为干燥，再保存确认。'], 'TODA 和 ASDA 不得小于 TORA；入口扣减必须小于 TORA。页面不将这些声明距离换算为起飞性能余量。'),
'21.2': ('样例 TOW 为 184 500 kg，使用 CONF 1+F、干跑道，防冰和空调引气关闭。', ['选择襟翼构型，核对防冰与引气选项。', '点击“保存并确认重量”，再点击“本地计算”。', '读取 V2 参考 150.8 kt，以及压力高度和风分量。', '对照当前航班及输入后，使用保存或导出按钮。'], '结果区域同时保留模型范围说明。没有显示的 V1、VR、FLEX 和距离项目并非零值。'),
'21.3': ('过期与不支持分别由输入身份变化和模型适用范围触发。', ['改变人数、燃油或天气后，观察旧结果变为过期。', '重新确认并计算，获得与当前输入一致的结果。', '选择湿跑道或打开尚未建模的防冰、引气选项，观察支持范围提示。', '按本次演示资料修正条件后再计算。'], '不支持状态不提供速度参考，相关导出按钮保持禁用；不要用旧屏幕上的数值替代新结果。'),
'21.4': ('历史保存计算时的输入和结果，最多保留 20 条记录。', ['取得当前有效参考结果后，点击“保存记录”。', '在本机历史中核对航班、时间和 V2。', '点击目标记录的“恢复输入（需重算）”。', '检查恢复的输入，重新确认并计算。'], '恢复输入不会把历史结果直接设置为当前有效结果。'),
'21.5': ('文件出口分别服务于机器读取、人工阅读和打印。', ['使用“导出结果 JSON”保存完整计算快照。', '使用“导出报告 HTML”生成可在浏览器独立阅读的核算单。', '点击“打印核算单”打开打印页面，再使用浏览器打印或保存 PDF。'], '若弹窗被浏览器阻止，先下载 HTML 再打开打印。当前结果过期时应先重算。'),
'21.6': ('下降顶点与着陆工具使用各自的输入和模型。', ['打开下降顶点页，手工输入当前高度 35 000 ft、目标高度 3 000 ft、下降角 3°，读取约 100 NM 的几何距离。', '需要下降率或时间估计时，再填写所需地速条件。', '切换着陆工具，逐项输入质量、跑道、天气、襟翼和程序选项。', '读取三种自动刹车对应的距离，并保留完整输入条件供对照。'], '着陆算法的资料问题见第11章；不能将起飞参考值直接作为着陆进近速度。'),
'22.1': ('检查单页面将项目完成与整单确认分开显示。', ['选择当前需要的检查单，按顺序阅读条目。', '完成对应动作后点击人工项目；例如勾选 GEAR PINS & COVERS。', '检查尚未完成的项目及完成比例。', '全部项目核对后，使用整单确认入口。'], '条目全部完成后仍应观察整单确认状态，二者不应混为一个标志。'),
'22.2': ('复位用于重新进行检查，自动填写由配置及宿主条件共同决定。', ['需要重做当前清单时，使用当前清单复位。', '准备新一轮完整演示时，可使用全部清单复位。', '在设置中选择人工或自动填写方式，再观察有条件项目的更新。'], '人工项目仍需用户操作；启用自动填写不代表所有项目会立即完成。'),
'22.3': ('航图入口按 Navigraph、Local Files 和固定图件组织。', ['选择所需资料提供者，先检查登录或连接状态。', '取得图件后使用缩放、移动、旋转和页码控件。', '将常用图件固定到列表，之后从固定项返回原提供者。'], 'Local Files 依赖 SimBridge 资料服务，不等同于工作台的航班 JSON 文件选择器。无服务时保留连接提示。'),
'22.4': ('飞机预设与灯光预设采用不同的宿主请求和配置键。', ['打开飞机预设页面，查看可选择状态及执行进度区域。', '切换灯光预设，为需要使用的槽位填写名称。', '查看自动灯光对应的时段选择和保存入口。'], '在本地演示中，应按页面可见状态说明这些入口；真实飞机状态变化由所接入宿主执行。'),
'22.5': ('故障页按 ATA 系统分类，并提供搜索和活动状态显示。', ['选择需要查看的系统分类，或输入故障名称进行搜索。', '查看故障标识和当前活动状态。', '在具备对应宿主连接的环境中，通过激活或解除入口操作，并观察后续状态。'], '当前本地演示主要展示目录、筛选和请求接口，不能把页面按钮当作真实飞机故障执行证明。'),
'22.6': ('外部服务设置与本地核心业务相互独立。', ['进入设置中的外部服务页面，查看天气、通信和资料相关配置。', '在没有服务凭据的演示环境中，保持本地航班工作流。', '打开 About 查看当前版本和来源信息。', '结束演示前保存需要的航班文件和报告，再关闭或停止服务。'], '报告和航班文件不应携带服务凭据。跨设备转移以明确导出的业务文件为准。'),
}
